/* ÇEVİRİ pt · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pt","olay",{
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Ocupação grega de Uşak", "74ad2713"], "d": ["O exército grego prosseguiu o avanço com o objetivo de impor o Tratado de Sèvres, que Ancara não reconhecia. Segundo os verbetes Uşak e Luta Nacional do TDV, depois de Gediz, Uşak foi também ocupada em 29 de agosto de 1920. Mustafa Kemal Paşa inspecionara as unidades das Kuvâ-yi Milliye na cidade cerca de um mês antes desta ocupação.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Ocupação grega de İnegöl e Yenişehir", "4a0460e7"], "d": ["As tropas gregas em Bursa começaram a avançar para leste, na direção de Eskişehir. Segundo o verbete Luta Nacional do TDV, İnegöl e Yenişehir foram tomadas em 25 de outubro de 1920. Quando se percebeu que o avanço grego não podia ser detido com forças de milícia, a frente ocidental foi reorganizada com base num exército regular.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Fim da ocupação italiana de Burdur (ano)", "609123c8"], "d": ["Burdur, ocupada pelos italianos em 28 de junho de 1919, conheceu, segundo o verbete Burdur do TDV, uma breve ocupação italiana entre 1919 e 1921. A fonte não indica o dia da evacuação; no mapa, a ocupação termina no início do ano de 1921. A Itália retirou-se totalmente da sua zona de ocupação na Anatólia no verão de 1921.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Segunda ofensiva do exército grego — ocupação de Bilecik, Afyon e Adapazarı", "9ae146e2"], "d": ["O exército grego, que desembarcara novas forças em Esmirna após a derrota do Primeiro İnönü, voltou a atacar antes de expirar o prazo reconhecido pela Conferência de Londres. Segundo o verbete Luta Nacional do TDV, os gregos ocuparam Bilecik e Afyon em 23 de março. No norte, Adapazarı sofreu também a ocupação grega em 25 de março.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Evacuação de Batum pelas forças turcas", "ba5745dc"], "d": ["Quando os britânicos se retiraram do Cáucaso em julho de 1920, evacuaram Batum e o governo da Geórgia apoderou-se da cidade. Segundo o verbete Batum do TDV, o Tratado de Moscovo, assinado em 16 de março de 1921 com a Rússia Soviética, cedeu Batum à Geórgia. As forças turcas evacuaram a cidade em 28 de março de 1921 e Batum tornou-se o centro da República Autónoma da Adjara, criada dentro da Geórgia.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Reconquista de Afyon — batalhas de Aslıhanlar", "2bbba17b"], "d": ["Depois de a ofensiva grega ter sido detida em 1 de abril no Segundo İnönü, Afyon foi reconquistada em 7 de abril na frente sul. O verbete Luta Nacional do TDV resume-o assim: «Derrotados gravemente em Aslıhanlar, Afyon foi reconquistada em 7 de abril»; contudo, os estudos de história militar situam os combates de Aslıhanlar-Dumlupınar entre 8 e 15 de abril, depois da evacuação de Afyon, e escrevem que a superioridade tática permaneceu do lado grego — as duas versões não coincidem e ambas são apresentadas. A vitória de İnönü foi celebrada com comícios em todo o país, a começar por Istambul.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Libertação de İzmit — na sequência de Adapazarı", "cec60e36"], "d": ["Adapazarı, que sofrera a ocupação grega em março de 1921, foi reconquistada em 21 de junho, segundo o verbete Adapazarı do TDV. Segundo o verbete İzmit do TDV, İzmit, ocupada em 6 de julho de 1920 primeiro pelos britânicos e depois pelos gregos, foi também libertada em 28 de junho de 1921. Ao abandonarem a cidade, os gregos incendiaram o bazar.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Libertação de Muğla da ocupação italiana", "143ddf98"], "d": ["A Itália começou a retirar-se da sua zona de ocupação na Anatólia no verão de 1921; a evacuação de Antália começara em 1 de junho. Segundo o verbete Muğla do TDV, Muğla, sob ocupação italiana desde 23 de julho de 1919, foi libertada em 5 de julho de 1921.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Evacuação de Eskişehir — o exército grego entrou em Eskişehir, Kütahya e Bilecik", "a948a74d"], "d": ["O exército turco, apanhado desprevenido nas batalhas de Kütahya-Eskişehir, recuou para leste do Sakarya por ordem de Mustafa Kemal Paşa. Segundo os verbetes do TDV, os gregos entraram em Eskişehir em 20 de julho de 1921, em Kütahya em 21 de julho e em Bilecik em 22 de julho. O rei grego Constantino presidiu a um conselho de guerra em Kütahya em 28 de julho e o exército preparou-se para atacar na direção de Ancara.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Retirada das tropas italianas de Marmaris e Kuşadası", "1d672994"], "d": ["Os italianos, presentes na costa do sudoeste da Anatólia desde maio de 1919, evacuaram a sua zona de ocupação passo a passo, após a aproximação ao governo de Ancara. Antália e Bodrum tinham sido evacuadas no verão de 1921; as últimas tropas italianas deixaram também Kuşadası e Marmaris no final de abril de 1922.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Início da Grande Ofensiva", "efba4bd3"], "d": ["Após um ano de preparação depois do Sakarya, o exército turco lançou a ofensiva geral na frente de Afyon. Segundo os verbetes Luta Nacional e Kütahya do TDV, a Grande Ofensiva começou de Afyon na manhã de 26 de agosto de 1922 e a resistência do exército grego foi rapidamente quebrada.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Libertação de Afyon", "beaeef23"], "d": ["No segundo dia da ofensiva, a frente grega foi rompida diante de Afyon. Segundo o verbete Afyonkarahisar do TDV, no final da Grande Ofensiva, comandada pessoalmente por Atatürk, as forças gregas foram postas em debandada e a cidade foi libertada em 27 de agosto de 1922. Este dia é celebrado como o dia da libertação de Afyon.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["Batalha Campal do Comando Supremo — libertação de Kütahya", "376d3118"], "d": ["As forças principais do exército grego foram cercadas entre Afyon e Dumlupınar. Segundo o verbete Luta Nacional do TDV, a operação de cerco foi concluída em 30 de agosto com a Batalha do Comando Supremo, dirigida pessoalmente pelo comandante-chefe Mustafa Kemal Paşa. Segundo o verbete Kütahya do TDV, no mesmo dia uma divisão de cavalaria libertou Kütahya, que as forças gregas em retirada tinham incendiado e destruído.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Libertação de Uşak", "0f2d44d1"], "d": ["Após a Batalha do Comando Supremo, os restos do exército grego recuaram para oeste, na direção de Esmirna. Segundo o verbete Uşak do TDV, Uşak, sob ocupação desde 29 de agosto de 1920, foi libertada em 1 de setembro de 1922 com a entrada das forças nacionais na cidade. No incêndio provocado pelas forças de ocupação em retirada, ardeu cerca de três quartos da cidade.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Libertação de Eskişehir", "f442de5c"], "d": ["No flanco norte da Grande Ofensiva, as forças gregas tiveram de abandonar também Eskişehir. Segundo o verbete Eskişehir do TDV, a cidade, sob ocupação desde 20 de julho de 1921, foi libertada em 2 de setembro de 1922, após a vitória de 30 de agosto. No fim de treze meses de ocupação, o bazar tinha sido incendiado e a cidade ficara meio destruída.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Libertação de Bilecik", "35dbd49b"], "d": ["Segundo o verbete Bilecik do TDV, a cidade sofreu a ocupação grega três vezes durante a Luta Nacional; a terceira ocupação, iniciada em 22 de julho de 1921, terminou em 6 de setembro de 1922. No incêndio provocado pelas forças gregas ao evacuarem a cidade, ardeu a maior parte das casas, das lojas e do edifício do governo.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Libertação de Aydın", "ef1280b5"], "d": ["Com a aproximação do exército turco a Esmirna, as forças gregas no vale do Menderes também recuaram. Segundo o verbete Aydın do TDV, a cidade foi libertada pelas forças turcas em 7 de setembro de 1922, parcialmente destruída e com a população muito reduzida. Os gregos em retirada tinham incendiado a maior parte da cidade.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Reconquista de Bursa", "6ad1da0b"], "d": ["Após a libertação de Esmirna, o exército turco avançou para norte, em direção à costa do Mármara. Segundo o verbete Bursa do TDV, a cidade, sob ocupação grega desde 8 de julho de 1920, foi reconquistada em 10-11 de setembro de 1922. A marcha do exército daí para Çanakkale alarmou os britânicos e abriu caminho às conversações de Mudanya.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Receção da Trácia Oriental — Kırklareli e Tekirdağ", "2a08d65c"], "d": ["O Armistício de Mudanya previa a evacuação da Trácia Oriental pelo exército grego e a sua entrega à Turquia; Refet Paşa, encarregado de receber a Trácia, chegou a Istambul em 19 de outubro. Segundo o TDV, Kırklareli, sob ocupação desde 26 de julho de 1920, foi reconquistada em 10 de novembro de 1922 e Tekirdağ foi também devolvida aos turcos em 13 de novembro, em conformidade com o armistício. Assim, a Trácia Oriental foi integrada nas terras turcas sem combate.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna anexou as regiões de Tokat, Kayseri e Samsun", "4a088f9f"], "d": ["O emir Eretna, que ganhara poder na Anatólia como governador ilcânida, depois de recuperar o apoio do sultão mameluco al-Nâsır Muhammed, alargou em 1339 as suas fronteiras e anexou as regiões de Tokat, Kayseri e Samsun. A região de Zamantı, a leste de Kayseri, passou também nesta época para a administração de Eretna. O beilhique declarou a independência em 1341, com a morte de al-Nâsır.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Halil Bey de Dulkadir alargou as suas fronteiras até Zamantı", "aa911e87"], "d": ["Com a subida de Mehmed Bey, ainda menor, à chefia do Beilhique de Eretna, os ataques turcomanos do sul contra as terras enfraquecidas de Eretna aumentaram. Em 1360, enquanto o chefe turcomano Ömer Bey tomava Malatya, Halil Bey de Dulkadir alargou também as fronteiras do seu beilhique até Zamantı, a leste de Kayseri. Assim, a região de Zamantı, entre Elbistan e Kayseri, passou para as mãos dos Dulkadir e o beilhique manteve esta região até à anexação otomana de 1515.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Bajazeto o Relâmpago voltou a pôr Constantinopla sob um cerco apertado", "244834ca"], "d": ["Constantinopla, bloqueada intermitentemente desde 1391, foi de novo sujeita a um cerco apertado por Bajazeto o Relâmpago na primavera de 1394. A relação com Bizâncio, que pagava tributo aos otomanos e enviava ajuda militar desde 1371, transformou-se assim em hostilidade aberta. O cerco foi levantado com o surgimento da ameaça de Timur e com a Batalha de Ancara de 1402.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Paz de Murad II com Bizâncio — Bizâncio aceitou pagar de novo tributo", "6474d704"], "d": ["Murad II, que sitiara Constantinopla em 1422 contra Bizâncio, que apoiava o falso Mustafa, assinou em 22 de fevereiro de 1424 um tratado de paz com o imperador bizantino. Por este tratado, Bizâncio aceitou pagar de novo tributo aos otomanos e restituir os lugares que tomara depois de 1402 nas costas do Mármara, do Egeu e do Mar Negro, com exceção das fortalezas de Silivri e Terkos; o tributo anual de que se libertara pelo tratado feito em 1403 com o emir Süleyman foi assim restabelecido. Bizâncio manteve esta situação até à conquista de Constantinopla em 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Fortalezas de Bayburt e Kiğı recebidas dos safávidas — Erzincan e Bayburt entregues a Bıyıklı Mehmed Bey", "2c7fd65e"], "d": ["Quando Selim o Inflexível, de regresso de Tabriz após a vitória de Çaldıran, estava no acampamento, chegaram as notícias de que as fortalezas de Bayburt e Kiğı tinham sido entregues. Bıyıklı Mehmed Bey, sanjaco-bei de Trebizonda, e Mustafa Bey, sanjaco-bei de Yanya, tomaram em outubro de 1514 Bayburt, defendida por Kara Maksûd-i Sultânî, um dos emires do xá Ismâil. Erzincan, que passou sem combate para o domínio otomano, foi dada em 23 de outubro de 1514, juntamente com Bayburt, a Bıyıklı Mehmed Bey como beilerbeilique, e Bayburt foi tornada centro de um sanjaco.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Selim o Inflexível regressou da campanha de Tabriz a Amasya e passou aí o inverno", "49d51f94"], "d": ["Selim o Inflexível, que ficou nove dias em Tabriz, desistiu de passar o inverno no Irão por falta de víveres e por relutância dos soldados e regressou por Kars e Bayburt. O sultão, que passou o Ramadão Bayramı em Niksar, chegou a Amasya e passou aí o inverno. Tinha a intenção de marchar de novo contra os safávidas no ano seguinte; em Amasya começou a pressão dos janízaros para regressar a Istambul, e a campanha prosseguiu na primavera de 1515 com a conquista de Kemah.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["A Valáquia, a Moldávia e a Transilvânia revoltaram-se em conjunto contra os otomanos", "e71d3ee9"], "d": ["Em meados de 1594, os três voivodatos a norte do Danúbio — Valáquia, Moldávia e Transilvânia — decidiram agir em conjunto contra os otomanos. O voivoda da Moldávia, Aron Tiran, aderiu à Santa Aliança formada pelo imperador da Áustria e pelo papa Clemente VIII e submeteu-se ao Principado da Transilvânia; o voivoda da Valáquia, Mihai Viteazul, juntou-se ao movimento pelo descontentamento com o pesado fardo dos impostos. Em 13 de novembro de 1594 começaram revoltas simultâneas contra o domínio otomano na Valáquia e na Moldávia e, com o apoio da Transilvânia, o movimento alastrou para sul do Danúbio, para território otomano. Segundo a Enciclopédia Islâmica do TDV, esta aliança tripla abriu a frente norte da Longa Guerra Otomano-Habsburgo (1593-1606), que decorria nesses anos.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Conquista da Fortaleza de Ostrovica no vale do Una", "5c6cc91b"], "d": ["Ostrovica, em mãos dos Frankapan e de outros nobres croatas, situava-se sobre uma crista escarpada que ligava as partes norte e sul do vale do Una. Passou para a administração otomana em 1523 e teve guarnição otomana até 1878. A fortaleza ganhou a sua verdadeira importância depois de Karlowitz (1699): pela proximidade da fronteira veneziana e austríaca, foi ampliada e tornou-se o centro do capitanato de Stara Ostrovica; a povoação de Kulen Vakuf foi fundada no início do século XVIII na sua base.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Conquista das fortalezas de Udbina e Krbava — a Lika entra na administração otomana", "5fe329d3"], "d": ["A planície de Krbava fora despovoada em 1524 e em Udbina restava apenas a guarnição de Karlović. Karlović obteve em abril de 1527 uma última vitória diante da fortaleza, mas no fim de maio Udbina, juntamente com as fortalezas de Mrsinj e Komić, passou para as mãos do paxá da Bósnia. No mesmo ano, a região de Gospić foi dada aos aghas Senković. A Lika e a Krbava passaram depois a fazer parte do sanjaco com centro em Obrovac que, em 1580, recebeu o nome de Kırka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Passagem definitiva de Drežnik e do condado (županija) de Drežnik para a administração otomana", "6624ad14"], "d": ["Drežnik, em mãos dos Frankapan desde 1323, fora mantida provisoriamente pelos otomanos em 1578. Em 1592, a fortaleza e todo o condado de Drežnik passaram definitivamente para a administração otomana; no mesmo ano caiu também Bihać. No século XVIII, Drežnik estava ligada ao capitanato de Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Tomada da Fortaleza de Cetin pelos otomanos", "98815f97"], "d": ["Cetin, fortaleza-chave na defesa da região de Slunj contra os otomanos desde meados do século XVI, passou para a administração otomana em 1636, depois de ter sido repetidamente sitiada. Este primeiro período otomano durou dois anos.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["A Fortaleza de Cetin volta para o lado Habsburgo", "690f9f84"], "d": ["Cetin, que passara em 1636 para mãos otomanas, voltou em 1638 à defesa da fronteira croata-Habsburga e assim permaneceu até 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin torna-se de novo fortaleza otomana", "e1750675"], "d": ["Cetin tornou-se de novo fortaleza otomana em 1670 e foi solidamente fortificada no século XVIII: a fortaleza medieval foi cercada por muralhas com baluartes. A fortaleza manteve até 1790 a extremidade noroeste da fronteira da Bósnia.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Perda da Lika e da Krbava — Udbina e Gospić passam para as forças fronteiriças Habsburgas", "01277a38"], "d": ["Na guerra que prosseguiu depois do desastre de Viena, as tropas fronteiriças croatas, comandadas pelo general de Karlovac Herberstein, tomaram Udbina em 1689; também Gospić saiu no mesmo ano da administração otomana. Terminou a Lika otomana, de mais de 160 anos, os lugares despovoados foram repovoados com nova população croata e Udbina foi, até à paz de Sistova (1791), uma importante fortaleza da defesa fronteiriça contra os otomanos.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Tomada de Drežnik pelos austríacos — frente ocidental da Batalha de Dubica", "05d5e5f1"], "d": ["Na guerra otomano-austríaca de 1788-1791, as forças Habsburgas tomaram Drežnik, a oeste de Bihać. Pelo artigo 4.º do Tratado de Sistova, Drežnik e Cetin permaneceram sob administração Habsburga e nunca voltaram à Bósnia.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Tomada da Fortaleza de Cetin pelos austríacos", "df182480"], "d": ["Em 1790, o exército Habsburgo atacou Cetin, Bužim e Velika Kladuša e tomou Cetin. A mobilização e o contra-ataque declarados pelo governador da Bósnia não conseguiram retomar a fortaleza; o artigo 4.º do Tratado de Sistova deixou Cetin aos Habsburgos. Os homens de fronteira bósnios retomaram a fortaleza em breves incursões em 1809 e em 1813.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik é mencionada pela primeira vez — a fronteira com Bizâncio começava em Bilecik", "7b69f743"], "d": ["Nos acontecimentos do ano 683 relatados por Neşrî, Bilecik surge como o lugar onde começava a fronteira entre o beilhique de fronteira de Osman Bey e Bizâncio. É a primeira menção conhecida do povoado na história; não é a sua fundação.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Moeda em nome de Gāzân Han em Burdur — primeira testemunha conhecida da cidade", "01974ddc"], "d": ["Os Hamidoğulları foram obrigados, sob pressão ilcânida, a mandar cunhar em Burdur, no ano 699, moeda em nome de Gāzân Han. Esta moeda é a primeira testemunha escrita/datada de Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum é mencionada no território de Eretna — primeira testemunha conhecida da cidade", "bf7bd67f"], "d": ["Na morte de Eretna Bey, em Muharrem 753, Çorum conta-se entre as cidades sob o seu domínio. A fundação da cidade é desconhecida; esta menção é a testemunha datada mais antiga que se pôde encontrar.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Brăila é mencionada pela primeira vez — privilégio de Vlaicu Vodă aos mercadores de Brașov", "0b3517a7"], "d": ["O voivoda da Valáquia Vladislav concedeu aos mercadores de Brașov um documento que lhes dava facilidades ao transportarem mercadorias pela estrada de Brăila. Este documento é a primeira testemunha escrita conhecida de Brăila; o lugar surge aqui ainda não como cidade, mas como o extremo da estrada no Danúbio. Não é a data da fundação.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Chișinău foi mencionada pela primeira vez num decreto do voivoda da Moldávia", "a50799d7"], "d": ["O nome de Chișinău aparece pela primeira vez num decreto de 1420 do voivoda da Moldávia Alexandru. A cidade permaneceu durante muito tempo uma pequena vila moldava; quando passou para a Rússia com a Bessarábia em 1812, tornou-se centro da província.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Galați é mencionada pela primeira vez num documento de um voivoda da Moldávia", "a31af8a2"], "d": ["O voivoda da Moldávia Ștefan II isentou de direitos aduaneiros duas carroças do Mosteiro de Humor que traziam peixe de Galați. Este documento é a primeira testemunha escrita com certeza conhecida de Galați; o povoado pode ter existido antes como aldeia de pescadores na margem do Danúbio.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["O nome de Mostar aparece pela primeira vez num documento de Dubrovnik", "a599bc55"], "d": ["O nome de Mostar aparece pela primeira vez num documento de Dubrovnik de 3 de abril de 1452; o povoado situava-se em território do Ducado da Herzegovina. A conquista otomana deu-se em 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["A Mesquita Hünkâr em Saraievo — a testemunha datada mais antiga do povoado", "ad697a7d"], "d": ["İshak Bey, sanjaco-bei da Bósnia, mandou construir, no primeiro povoado muçulmano na planície de Saray, um palácio para si, a Mesquita Hünkâr em nome do sultão Maomé II, o Conquistador, e um banho ao lado. A mesquita data de 862 (1458); é a construção datada mais antiga conhecida de Saraievo.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Fundação pia de İshak Bey — o núcleo urbano de Saraievo foi dotado como vakıf", "0b364229"], "d": ["Da fundação pia de İshak Bey, datada de Cemâziyelevvel 866 (fevereiro de 1462), depreende-se que, além da mesquita e do banho, foram construídos uma zâviye, uma mevlevîhâne, um imaret, uma ponte sobre o Miljacka, na margem oposta o Kolobara Hanı, um bedesten, um caravançarai e lojas. O documento é a base de vakıf da cidade; o povoado existia antes dele.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarcığı está registada pela primeira vez num registo de akıncı", "3b1c839e"], "d": ["Os registos mais antigos sobre a cidade remontam ao ano 877 (1472): um registo de akıncı na Biblioteca Nacional de Sófia regista o povoado.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka é mencionada pela primeira vez numa instrução do rei Vladislau II", "0ebc6288"], "d": ["O nome Banja Luka aparece pela primeira vez numa instrução de 6 de fevereiro de 1494 do rei húngaro-croata Vladislau II; a região estava ligada à coroa húngara através do banato de Jajce. A conquista otomana deu-se no inverno de 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["A população de Baçorá conclui a mudança para o local atual — a antiga Baçorá é abandonada", "20f96eac"], "d": ["A população começara com o tempo a fixar-se na atual Baçorá, que considerava mais segura contra os ataques beduínos e onde podia obter água mais facilmente; a passagem para o novo local concluiu-se no ano 900 (1494-95). A antiga Baçorá, fundada no tempo do califa Omar, ficava a cerca de 25 km da cidade atual.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giray Han mandou construir o Palácio do Cã junto ao Çürüksu — fundamento de Bahçesaray", "0792497c"], "d": ["No vale, zona de caça e repouso de verão dos governadores da Horda Dourada e dos primeiros cãs da Crimeia, Mengli Giray Han I lançou os alicerces de Bahçesaray ao mandar construir junto ao Çürüksu o palácio hoje conhecido como Palácio do Cã. A cidade desenvolveu-se em redor do palácio e ao longo do estreito vale do Çürüksu, prosperou nos finais do século XVI e tornou-se o centro do Canato da Crimeia.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Os cossacos zaporozhianos fundaram o primeiro Sich na ilha de Khortytsia", "e6ca0dd9"], "d": ["O príncipe Dmytro Vyshnevetsky fundou o primeiro Sich zaporozhiano na ilha de Pequena Khortytsia, no Dniepre. A fortaleza foi sitiada e destruída em 1558 pelos tártaros da Crimeia; o Sich foi depois transferido para as ilhas a sul. Termo: «Sich» (em ucraniano Sich) é o acampamento central dos cossacos zaporozhianos nas ilhas do Dniepre, fortificado com troncos e fossos; é o quartel-general, o lugar da assembleia (Rada) e o centro do chefe eleito do exército (koshovy), não uma capital de Estado.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Fundado o Sich de Bazavluk", "fcd507ae"], "d": ["Depois de os tártaros destruírem o Sich de Tomakivka, os cossacos zaporozhianos fundaram um novo Sich na ilha de Bazavluk, na confluência do Dniepre com os seus braços Chortomlyk, Pidpilna e Skarban. O Sich foi destruído em 1638 com a campanha polaca que se seguiu à repressão da revolta cossaca. Termo: «Sich» (em ucraniano Sich) é o acampamento central dos cossacos zaporozhianos nas ilhas do Dniepre, fortificado com troncos e fossos; é o quartel-general, o lugar da assembleia (Rada) e o centro do chefe eleito do exército (koshovy), não uma capital de Estado. Nesta data o «Hetmanato» ainda não existe (1648); o nome Zaporozhia significa «para lá dos rápidos» e os Sich ficam na fronteira da estepe, a jusante dos rápidos do Dniepre. Não há parentesco étnico com os cossacos do Cazaquistão: os cossacos zaporozhianos são uma comunidade eslava oriental (ucraniana), ortodoxa; o que há de comum é apenas a palavra «cossaco» (guerreiro livre), de origem turca.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["O Sich de Mykytyn Rih é mencionado pela primeira vez", "61e22abc"], "d": ["O nome do quarto Sich, fundado em Mykytyn Rih, no local da atual Nikopol, surge pela primeira vez em 1628; foi tomado em 1648 por Bohdan Khmelnytsky. Esta é a primeira testemunha conhecida do lugar, não a sua fundação.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Fundado o Sich de Chortomlyk", "4b6e8197"], "d": ["Os cossacos zaporozhianos fundaram o Sich de Chortomlyk, também chamado «Sich Velho», no promontório onde o Dniepre se junta ao rio Chortomlyk. O Sich foi destruído pelo exército russo em 25 de maio de 1709 por ter apoiado Mazepa.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Carcóvia foi fundada por emigrantes cossacos", "288b303c"], "d": ["No limite norte da Estepe Selvagem, na confluência dos rios Lopan e Carcóvia, emigrantes cossacos vindos da margem direita do Dniepre fundaram um povoado. Carcóvia tornou-se rapidamente o centro da Ucrânia Sloboda, ligada a Moscovo.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Os cossacos zaporozhianos fundaram o Sich de Oleshky com licença do cã da Crimeia", "ed26f29d"], "d": ["Quando a ofensiva russa os fez evacuar o Sich de Kamianka, os cossacos zaporozhianos instalaram-se, com licença do cã da Crimeia, em Oleshky, na margem esquerda do rio Konka, em território do canato. Depois do Tratado do Prut, os cossacos de Gordiienko juntaram-se-lhes. O cã não permitiu que o Sich tivesse muralhas nem canhões.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["O Sich de Oleshky foi saqueado e abandonado", "52361709"], "d": ["Os cossacos de Samara, pró-russos, assaltaram e saquearam o Sich de Oleshky e incendiaram os quartéis. O Sich não foi refundado; os cossacos regressaram a Kamianka em 1730 e, em 1734, prestando juramento de fidelidade à Rússia, fundaram o Novo Sich.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Fundada a fortaleza de Stavropol na margem do Volga", "eb087a50"], "d": ["No Volga médio, foi fundada a fortaleza de Stavropol para os calmucos convertidos ao cristianismo (hoje Togliatti).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nâdir Xá toma Kandahar e manda destruir a cidade antiga", "9cc23e6b"], "d": ["O soberano afexárida Nâdir Xá tomou, após um longo cerco, Kandahar, que estava nas mãos dos afegãos Ghilzai. A cidade foi destruída e a sua população passou para Nâdirâbâd, fundada a sudeste do seu antigo local; a antiga Kandahar nunca mais foi cidade.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Fundada a fortaleza de Stavropol na linha Azov-Mozdok", "7fd9b9f1"], "d": ["Na linha de fortificações Azov-Mozdok, criada depois de Küçük Kaynarca para controlar a estepe entre o Kuban e o Terek, foram construídas dez fortalezas; uma delas era Stavropol. A fortaleza tornou-se mais tarde o centro do governo do Cáucaso e da província de Stavropol.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Fundado o estaleiro de Kherson na foz do Dniepre", "115f2c34"], "d": ["Na foz do Dniepre, que passou para a Rússia depois de Küçük Kaynarca, perto da fortificação de Aleksandr-shants, construída em 1737 e rapidamente destruída, foi fundado um estaleiro, a que se deu o nome de Kherson. A cidade tornou-se sede de distrito em 1784 e centro de governo em 1803.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Os gregos vindos da Crimeia fundaram Mariupol na costa do Azov", "4e3af209"], "d": ["Os gregos vindos da Crimeia fundaram Mariupol no local onde o Kalmius desagua no Mar de Azov. A cidade tornou-se em 1784 sede de distrito ligada ao governo de Iekaterinoslav.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Iekaterinoslav mudou-se para o seu local atual, na margem do Dniepre", "ec361381"], "d": ["Iekaterinoslav, fundada por Potemkin em 1778 na confluência dos rios Kilçen e Samara, foi transferida em 1783 para o seu local atual por causa da sua localização insalubre.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Fundado o porto naval russo de Sebastopol na baía de Akhtiar", "01058a25"], "d": ["Depois da anexação da Crimeia pela Rússia em 1783, a baía onde ficava a aldeia tártara da Crimeia de Akhtiar (Akyar) foi escolhida para porto militar; o porto foi fundado no ano seguinte e recebeu o nome de Sebastopol. A cidade tornou-se em 1804 o principal porto da frota russa do Mar Negro.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Fundada a fortificação de Nikolaiev na foz do Bug", "d57e52b9"], "d": ["Na confluência dos rios Bug Meridional e Ingul, por ordem do cnezi Potemkin, foi fundada uma fortificação. Em 1788 abriu-se aí um estaleiro e o povoado tornou-se um dos centros de construção naval da frota do Mar Negro.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Fundado, na margem do Molochna, o povoado fronteiriço que é o núcleo de Melitopol", "637d5817"], "d": ["Depois da anexação da Crimeia, foi fundado um povoado fronteiriço na margem do rio Molochna. O povoado recebeu em 1816 o nome de Novooleksandrivka e foi feito cidade em 1841 com o nome de Melitopol.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Fundada Novocherkassk, o novo centro do Exército Cossaco do Don", "bf5709fd"], "d": ["O centro administrativo do Exército Cossaco do Don passou de Cherkassk, que até então era o centro, para Novocherkassk, fundada no local de Biriuchi Kut, entre os rios Aksai e Tuzlov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Wadi Halfa é registada na viagem de Burckhardt pela Núbia", "6efc72ec"], "d": ["O viajante suíço J. L. Burckhardt escreve no seu diário de 6 de março de 1813 que passou por Wadi Halfa e que aí se fazia algum comércio. É a primeira testemunha datada que se pôde encontrar.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Fundado o cais de Berdiansk na costa do Azov", "908ac3cf"], "d": ["Por iniciativa do cnezi Mikhail Vorontsov, Berdiansk foi fundada no local onde o rio Berda desagua no Mar de Azov. O povoado tornou-se cidade em 1835 e sede de distrito em 1842.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["A população de Malatya fica nas vinhas de Aspuzu — o núcleo da Malatya moderna", "d1dba159"], "d": ["O quartel-general otomano, contra o exército egípcio de İbrâhim Paşa, foi transferido de Mezraa para Malatya no verão de 1838. Os habitantes de Malatya, que residiam nas suas casas de verão em Aspuzu, não regressaram, depois da partida do exército, às suas casas de inverno na cidade antiga, que ficara em ruínas; Aspuzu tornou-se o núcleo da Malatya moderna. A antiga Malatya (Battalgazi) continuou a viver, diminuída.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van é fundada no novo local — a antiga cidade em ruínas é abandonada", "6d278578"], "d": ["Van foi libertada da ocupação em 2 de abril de 1918. Os que regressaram, em vez de reparar a antiga Van junto ao lago, arruinada nos anos de guerra, fundaram uma nova cidade cerca de 7 km para o interior da margem, no local dos antigos bairros de Norşen e Arak. A cidade antiga foi abandonada.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş passa para os mamelucos — o naib de Alepo Bilbân et-Tabahî retoma-a aos arménios", "03171265"], "d": ["Maraş, que estava desde 1258 nas mãos do Reino Arménio da Cilícia, passara por pouco tempo para os mamelucos em 1293, com o tratado feito pelo sultão Halil com os arménios, e depois da sua retirada voltara a cair em mãos arménias. Em 697 (1298), o naib mameluco de Alepo Bilbân et-Tabahî retomou a cidade. Maraş permaneceu depois como território mameluco até à ascensão dos Dulkadır.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["O Império Bizantino torna-se tributário dos otomanos", "615df998"], "d": ["Depois da vitória de Çirmen (1371), o imperador bizantino João V aceitou no inverno de 1372 tornar-se tributário de Murad I: pagaria um tributo anual e forneceria soldados para as campanhas do sultão. Bizâncio permaneceu desta data até 1403 como Estado vassalo ligado aos otomanos; o bloqueio de Bajazeto I, o Relâmpago, em 1391 aumentou o tributo. Depois do desastre de Ancara, o tratado de Galípoli (1403) feito com Süleyman Çelebi libertou Bizâncio do tributo; em 1424, com o tratado feito com Murad II, o tributo recomeçou.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Bajazeto I, o Relâmpago, incorpora Besni, Darende e Divriği no território otomano depois da morte de Berkuk", "8e57d7e6"], "d": ["Quando, depois da morte do sultão mameluco Berkuk (junho de 1399), os assuntos administrativos do Estado Mameluco se desordenaram, Bajazeto I, o Relâmpago, desceu à bacia do Eufrates e incorporou no território otomano, juntamente com Malatya, Besni (Behisni), Darende e Divriği. Sivas fora antes deixada aos otomanos depois da morte de Kadı Burhâneddin no verão de 1398. Divriği estava desde 1391 sob domínio mameluco e era um posto avançado ligado à província de Alepo. A administração otomana não durou aqui muito: por causa do perigo de Timur, que se aproximava, Divriği foi de novo dada aos mamelucos em 1401, e a entrada definitiva da cidade na administração otomana deu-se depois de Marj Dabiq, em 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni passa para os mamelucos durante a campanha de Timur contra Sivas e Malatya", "4853da9a"], "d": ["Besni, que Bajazeto I, o Relâmpago, tomara em 1398 com Sivas, Darende e Malatya, passou para as mãos dos mamelucos quando, em 1400, Timur tomou Sivas e Malatya. Timur tomou também Besni a 27 de setembro de 1400, depois de um violento cerco; quando se retirou da região, Besni voltou ao domínio mameluco e permaneceu mameluca (salvo um período intermédio dos Dulkadır) até que Selim I, o Severo, a tomou em agosto de 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği volta a ser dada aos mamelucos por causa do perigo de Timur", "97196b1f"], "d": ["Divriği, que Bajazeto I, o Relâmpago, tomara aos mamelucos em 1398, foi de novo deixada aos mamelucos em 1401, com a aproximação de Timur à Anatólia. Por isso, depois de Timur ter arrasado Sivas (1400), Divriği aparece no mapa com a cor mameluca; nos mesmos meses, Bajazeto tomava no leste Erzincan e Kemah, isto é, o território mameluco ficou entre os territórios otomanos do oeste (Sivas) e do nordeste (Kemah). Divriği só passou definitivamente para os otomanos depois de Marj Dabiq, em 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["O sultão mameluco Şeyh retoma Antep e Darende aos Dulkadır", "f90c9508"], "d": ["O sultão mameluco Şeyh, preocupado com a amizade dos Dulkadır com os otomanos, pôs-se em campanha em 1414; retomou Antep e Darende, que antes dera por sua vontade aos Dulkadır.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Mehmed Bey dos Dulkadıroğulları retoma Darende e incorpora também Besni nos seus territórios", "df914dcb"], "d": ["Mehmed Bey dos Dulkadıroğulları retomou em 1418 Darende, que os mamelucos tinham tomado em 1414, e incorporou também Besni nos seus territórios.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Os mamelucos derrotam os Dulkadır em Antep; Besni volta à administração mameluca (aproximado)", "72742430"], "d": ["O exército mameluco derrotou os Dulkadır em Antep em 1436 e Mehmed Bey retirou-se para Akdağ. O ano do regresso de Besni ao domínio mameluco não está escrito na fonte; Besni fora incorporada nos Dulkadır em 1418 e voltara a ser mameluca antes de Şehsuvar Bey a tomar aos mamelucos em 1465. O atlas devolve Besni aos mamelucos juntamente com esta derrota no centro vizinho de Antep (aproximação declarada).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Şehsuvar Bey dos Dulkadıroğulları toma Besni aos mamelucos (aproximado)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), nomeado bei dos Dulkadır por Maomé II, o Conquistador, tomou Besni, Gerger, Birecik e Rumkale, que estavam em mãos dos mamelucos; os mamelucos foram derrotados no outono de 1467 em Turnadağı e na primavera de 1468 perto de Antep.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["O emir Yeşbek derrota Şehsuvar Bey; Besni volta à administração mameluca (aproximado)", "4d856aee"], "d": ["Na primavera de 1471, o emir Yeşbek derrotou Şehsuvar Bey no ribeiro de Savron; os mamelucos retomaram Kadirli e Kozan. Şehsuvar foi executado em 1472 no Cairo e os mamelucos recolocaram Şahbudak à frente do beilique. Também Besni entrou, com este regresso, na administração mameluca (TDV besni: 'por volta do fim do século XV passou de novo para as mãos dos mamelucos').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["As forças de Fernando ocupam e fortificam Solnok", "6c8416e6"], "d": ["Quando os otomanos se preparavam para construir uma fortaleza em Solnok, no Tisza, as forças de Fernando I anteciparam-se: em meados de setembro de 1550 ocuparam Solnok e a fortaleza ficou defensável em meados de outubro. Assim, Solnok, que pertencia ao país de Isabel, passou para mãos Habsburgas um ano antes da passagem da Transilvânia para Fernando; os otomanos tomaram a fortaleza em 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["A Transilvânia passa para a administração dos Habsburgos: a dieta de Kolozsvár reconhece a abdicação de Isabel", "8458a566"], "d": ["Por causa do acordo de Martinuzzi com Fernando, a rainha Isabel assinou, em nome do pequeno rei János Zsigmond, a 19 de junho de 1551, na fortaleza de Szászsebes, a renúncia que lhe fora imposta. A dieta da Transilvânia, reunida a 26 de julho em Kolozsvár, reconheceu esta renúncia e a soberania do rei Fernando; o exército Habsburgo do general Castaldo entrou em Belgrado da Transilvânia (Gyulafehérvár). Assim, a Transilvânia, ligada aos otomanos, passou para uma administração Habsburga que duraria cinco anos.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Fim da administração Habsburga na Transilvânia: a Transilvânia volta a ser voivodato ligado aos otomanos", "721a482a"], "d": ["Os Habsburgos, por intermédio do padre de origem croata Martinuzzi (Fráter György), nomeado tutor de János Zsigmond por este ser menor, tentaram em 1551 dominar a Transilvânia; Belgrado da Transilvânia (Gyulafehérvár), Kaloşvar, Brassó e Segesvár permaneceram cinco anos sob administração Habsburga. Os otomanos impediram esta situação e a Transilvânia voltou a ser um voivodato tributário ligado a eles. A Transilvânia conservou depois, durante cerca de 150 anos, nos séculos XVI e XVII, o seu estatuto assente numa ampla autonomia nos assuntos internos e na vassalagem a Istambul nos assuntos externos.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt e Tokaj passam para o lado de Szapolyai", "587c782d"], "d": ["Depois do regresso de Isabel e de János Zsigmond à Transilvânia em 1556, os partidários de Szapolyai sitiaram Nagyvárad em 1556. Em 1557, os aristocratas do Alto Tisza tomaram as mais importantes fortalezas reais — Várad, Huszt e Tokaj; nas mãos de Fernando restaram apenas Gyula e Világos. Várad tornou-se depois a fortaleza do principado da Transilvânia e assim permaneceu até que os otomanos a tomaram em 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi toma Szatmár — a extremidade norte da Transilvânia passa para os Habsburgos", "2256bb27"], "d": ["Szatmár, que passara para os Habsburgos em 1561 com a mudança de lado de Balassa Menyhért, fora retomada de surpresa por Báthory István no outono de 1564 e incorporada na Transilvânia. O comandante Habsburgo Lazarus von Schwendi passou à contraofensiva em fevereiro de 1565: Tokaj caiu a 9 de fevereiro, Szerencs quatro dias depois, e Szatmár passou, quase sem resistência, para as mãos das forças imperiais.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["As forças de Bocskai tomam Szatmár", "e93b098b"], "d": ["Quando a revolta de Bocskai se estendia ao nordeste da Hungria, Gyulaffy tomou Szatmár, que sitiava, a 21 de janeiro de 1605. A paz de Viena de 23 de junho de 1606 deixou o condado de Szatmár a Bocskai vitaliciamente; como não havia herdeiro varão, com a morte de Bocskai a 29 de dezembro de 1606 o condado voltou ao reino.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Morte de Bocskai István — o condado de Szatmár volta ao reino", "3721bb9b"], "d": ["O príncipe da Transilvânia Bocskai István morreu a 29 de dezembro de 1606 em Kassa. A paz de Viena (23 de junho de 1606) deixara-lhe vitaliciamente os condados, incluindo Szatmár, para voltarem ao reino na falta de herdeiro varão; por esta disposição, o condado de Szatmár passou de novo para o reino húngaro dos Habsburgos. A Transilvânia entrou na busca de um novo príncipe.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor toma o controlo do condado de Szatmár", "80263da1"], "d": ["Com a campanha de Bethlen Gábor na Hungria no outono de 1619, o condado de Szatmár passou para o controlo do príncipe da Transilvânia; em novembro de 1619, dirigia-se ao condado por carta. O pré-acordo de 23 de janeiro de 1620 e a paz de Nikolsburg deixaram a Bethlen vitaliciamente sete condados, incluindo Szatmár. Depois da morte de Bethlen (15 de novembro de 1629), a restituição dos condados ao reino concluiu-se a 30 de março de 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Concluída a restituição ao reino dos sete condados de Bethlen Gábor", "31b5968f"], "d": ["A paz de Nikolsburg deixara a Bethlen Gábor vitaliciamente sete condados da Alta Hungria, incluindo Szatmár. Depois da morte de Bethlen a 15 de novembro de 1629, a restituição dos condados ao reino começou com a instrução de 30 de novembro de 1629 e concluiu-se a 30 de março de 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György Rákóczi I recebe Szatmár", "f398635b"], "d": ["Na campanha de 1644 do príncipe da Transilvânia György Rákóczi I, a guarnição alemã de Szatmár passou para o serviço de Rákóczi e a fortaleza passou para as mãos da Transilvânia. A paz de Linz de 16 de dezembro de 1645 deixou a fortaleza aos herdeiros de Rákóczi enquanto um Rákóczi estivesse no trono da Transilvânia.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Perda de Nitra — De Souches retoma a fortaleza", "c71bf012"], "d": ["Nitra, que depois da conquista de Uyvar, em 1663, se rendera após breve resistência, foi sitiada a 15 de abril de 1664 pelo comandante imperial De Souches; a fortaleza rendeu-se a 3 de maio de 1664. Como o Tratado de Vasvár deixou os lugares tomados no estado em que se encontravam, Uyvar ficou com os otomanos e Nitra permaneceu em mãos Habsburgas.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Perda de Léva", "f311920e"], "d": ["De Souches, depois de Nitra, sitiou Léva a 9 de junho de 1664; a 13 de junho foi assinada a capitulação e a fortaleza estava a 14 de junho em mãos das forças imperiais. A batalha de Léva (Garamszentbenedek) de 19 de julho de 1664 não mudou o dono; terminou com a manutenção de Léva e de Nitra pelos Habsburgos.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroshenko entrega Chyhyryn a Samoilovych", "3b538237"], "d": ["O hetman da Margem Direita, sob proteção otomana, Petro Doroshenko, entregou a capital, Chyhyryn, a 19 de setembro de 1676, ao hetman da Margem Esquerda Samoilovych e às forças russas. Os otomanos depuseram Doroshenko e puseram no seu lugar Yuri Khmelnytsky; o cerco de 1677 para expulsar a guarnição russa de Chyhyryn fracassou e a fortaleza só foi tomada a 21 de agosto de 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Entrega das fortalezas do Banat da Transilvânia (Timişoara, Lippa, Lugos, Karánsebes) ao rei Fernando da Hungria", "0e354976"], "d": ["Em 1551, o exército Habsburgo comandado pelo general Castaldo entrou na Transilvânia; a rainha Isabel e o seu filho foram obrigados a renunciar aos seus direitos ao trono da Hungria. Martinuzzi, com a aprovação de Castaldo, enviou em meados de julho de 1551 Báthory Endre a receber, em nome de Fernando, as fortalezas de Timişoara, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek e Csanád. As fortalezas do sul da Transilvânia, sob proteção otomana, passaram assim para mãos Habsburgas; as campanhas do Legislador de 1551-1552 são a resposta a isso.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Nomeação de Petrovics Péter como sancakbeyi de Lugos e Karánşebeş", "bcbe73e4"], "d": ["A pedido insistente de Isabel e de Petrovics, o Legislador decidiu fazer regressar o pequeno János Zsigmond à Transilvânia. Por carta escrita de Alepo a 7 de abril de 1554, ordenou à Transilvânia que levasse a criança de volta ao seu país; mandou também os voivodas da Valáquia e da Moldávia ajudarem neste assunto Petrovics, que nomeou nessa ocasião sancakbeyi de Lugos e Karánşebeş. Lugos, conquistada em 1552, foi assim dada a Petrovics como sanjaco otomano.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Levantamento do cerco de Lippa — ataque do bân de Lugos a Timişoara", "be03430e"], "d": ["Na primavera de 1596, o paxá de Timişoara sitiou Lippa. Na noite de 10 para 11 de maio, por ordem do bân de Lugos da Transilvânia, Palatics György, os soldados de Buday György invadiram e incendiaram os arrabaldes de Timişoara; o facto de Borbély György ter feito disparar na fortaleza todos os seus canhões fez também o paxá crer que chegara socorro. O paxá retirou-se a 11 de maio de diante de Lippa e correu a proteger o seu próprio centro. Lugos estava então em mãos do Principado da Transilvânia.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Ocupação de Orsova pelas forças austríacas comandadas por Veterani", "1b4a4f6c"], "d": ["Na campanha de 1688, o general Veterani, depois de tomar Karánsebes, marchou sobre Orsova e ocupou-a também. A fonte não tem o dia da ocupação; usou-se a base do ano, 1 de janeiro de 1688.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Retoma de Orsova por Thököly e pelas forças otomanas", "c5645da9"], "d": ["Sobre Orsova, ocupada por Veterani em 1688, marcharam, depois da tomada de Vetislan, Thököly e os paxás otomanos. Depois de escaramuças sem importância, Thököly entrou em Orsova a 15 de julho de 1689. Heissler, que chegou com a notícia do perigo, vendo que a força à sua frente estava bem equipada de munições e navios, retirou-se para defender a Transilvânia. Em agosto, também o ataque de Herbeville diante da cidade não conseguiu retomar Orsova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["O sanjaco de Lugos entra na ocupação Habsburga (1691-1695)", "c8bcd6bd"], "d": ["O sanjaco de Lugos permaneceu sob ocupação Habsburga (alemã) de 1691 a 1695; Mustafa II reconquistou-o a 22 de setembro de 1695. No registo antigo, o período de 1689-1695 era um vazio declarado; a fatia 1691-1695 passa a ser pintada como Habsburga, e 1689-1691 continua vazio. A data foi tomada apenas como ano.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-13:0":{"b": ["A fortaleza de Lugos entra na administração Habsburga", "6a9d401f"], "d": ["A fortaleza de sanjaco de Lugoj, ligada ao eyalet de Tımışvar, estava em mãos otomanas desde 1695; com a rendição do centro do eyalet no termo do cerco de 1716, foi cedida à Monarquia dos Habsburgos. O registo antigo punha a passagem em 1 de janeiro de 1716, a base do ano.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Tomada de Orsova pelo exército Habsburgo (campanha de 1717)", "7a4faffe"], "d": ["Na campanha de 1717, o general Splényi chegou diante de Orsova a 27 de agosto e tomou facilmente a cidade; Orsova, que Mercy não conseguira tomar em 1716, passou assim para mãos Habsburgas. Como os favos das margens do Danúbio à sua volta (incluindo o troço de Đerdap, do lado da Sérvia) estão ligados ao ponto de povoamento mais próximo, Orsova, são pintados com o seu dono. A data foi tomada apenas como ano; o dia exato não está confirmado.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Passagem da palanka de Orsova para os otomanos — o guarda retira-se para Ada Kale", "de759b16"], "d": ["Na abertura da campanha de 1738, Hacı Mehmed Paxá, guarda de Vidin, atacou o baluarte de Erzsébet, no Danúbio. Na tarde de 8 de maio, uma força de 4-5 mil sipahis marchou da margem esquerda do Danúbio para Orsova e atacou a palanka de Orsova; o guarda austríaco, que sofreu cerca de cem baixas, retirou-se para Nova Orsova, isto é, a fortaleza insular de Ada Kale. Depois dos combates de Mehadia em julho, também Ada Kale passou para mãos otomanas em agosto de 1738; o Tratado de Belgrado de 1739 reconheceu a situação.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II toma Alacahisar, Niš e Şehirköy voltam aos otomanos", "54af926a"], "d": ["Depois da morte sem herdeiros do déspota sérvio Stefan Lazarević (1427), Murad II, alegando ser o legítimo herdeiro da Sérvia com base no casamento de Bajazeto I, o Relâmpago, com a princesa sérvia, pôs-se em movimento e tomou Alacahisar (1428). No mesmo ano, depois da morte de Lazarević, os otomanos retomaram também a fortaleza de Şehirköy — a cidade fora tomada por Stefan em 1412 e defendida contra Mûsâ Çelebi. Segundo o artigo Niş do TDV, os otomanos retomaram Niš no mesmo ano (831/1428). Assim, a linha que liga os vales do Grande Morava e do Nišava passou para o controlo otomano.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["O exército cruzado toma Şehirköy — ramo do Nišava da 'Longa Campanha'", "fdf6140c"], "d": ["O exército cruzado, liderado pelo rei Ladislau e pelo déspota sérvio Đurađ Branković, tomou Şehirköy em 1443. Na continuação da mesma campanha, as forças otomanas serão derrotadas em novembro no desfiladeiro de İzladi. Şehirköy foi de novo dada aos sérvios por Murad II depois do Tratado de Szeged (1444), mas passou para os otomanos em 1456, depois da morte de Đurađ Branković.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Estabelecido o domínio otomano definitivo na região de Alacahisar", "9715382a"], "d": ["Alacahisar, deixada a Branković no termo do tratado feito em 1444 com os delegados húngaros, voltou ao domínio turco nos anos que se seguiram à vitória de Varna. Esta segunda conquista da cidade não é documentada por um registo de guerra, mas por um registo fiscal: os registos de timar de algumas aldeias ligadas a Alacahisar datam do fim de 1453/início de 1454; contudo, é apenas um testemunho de aldeias — em 1454 as forças otomanas foram derrotadas nos arredores de Alacahisar e em 1455 Alacahisar foi deixada a Branković como fronteira. Segundo o TDV, o domínio otomano definitivo na região foi estabelecido em 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Fundação do Despotado da Moreia — Manuel Cantacuzeno em Mistra", "87660b82"], "d": ["O imperador bizantino João Cantacuzeno deu ao seu filho Manuel uma circunscrição administrativa separada na Moreia; assim nasceu o Despotado da Moreia, com centro em Mistra. Manuel governou até 1380; neste período, a cultura e a arte bizantinas floresceram em especial em Mistra. O despotado durou até à conquista de Maomé II, o Conquistador, em 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["O déspota Constantino toma Patras aos francos", "cb0dd18c"], "d": ["Constantino, déspota da Moreia (em 1449, último imperador bizantino), retomou Patras aos latinos; assim, este importante porto do noroeste da península foi também incorporado no despotado. Patras entrou no domínio otomano em 1458, na campanha da Moreia de Maomé II, o Conquistador.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača 'Duque de São Sava' — nascimento da Herzegovina", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, que reunira Hum e Trebinje num só beilique, revoltou-se contra o rei da Bósnia e proclamou-se 'Herzog (duque) de São Sava'; o título foi dado em 1448 pelo imperador Frederico III. O nome Herzegovina ('terra do Herzog') vem deste título. A Herzegovina passou a pouco e pouco para os otomanos a partir de 1466, tornou-se sanjaco em 1470; os seus territórios restantes foram anexados no início de 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Paz de Cracóvia — o Estado da ordem germânica transforma-se no Ducado da Prússia", "78666ddd"], "d": ["Alberto de Brandemburgo, grão-mestre dos Cavaleiros Teutónicos, não encontrando ajuda contra a Polónia, assinou a Paz de Cracóvia. O Estado da ordem (Ordensstaat) tornou-se, sob a suserania da Polónia, um ducado hereditário e secular, passado para a dinastia de Brandemburgo. O centro era Königsberg; Alberto fundou aí, em 1544, a Universidade Albertina. O ducado transformou-se em 1701 em Reino da Prússia.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proclamação da República da Áustria — fim da monarquia dos Habsburgos", "c84f316c"], "d": ["No dia seguinte àquele em que o imperador Carlos I, a 11 de novembro, se retirou dos assuntos do Estado, a Assembleia Nacional Provisória aprovou a lei sobre a forma do Estado e do governo e foi proclamada a república. O lugar da Áustria dos Habsburgos foi tomado pela Primeira República, com centro em Viena.", "f747ce09"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Batum sob domínio do Reino/Reinos da Geórgia — testemunho datado da fonte", "62cd2833"], "d": ["A fonte mostra a cidade de Batum nesta data sob administração do Reino/Reinos da Geórgia; a posse anterior não está datada na fonte (o atlas deixa vazio o que antecede esta data).", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["O Mervânî Nasrüddevle anexou Âmid ao seu emirado", "9fbc8c85"], "d": ["O emir mervânî Nasrüddevle Ahmed anexou Âmid (Diyarbekir) ao território do emirado; no ano seguinte tomou também Urfa.", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Merâga passou para o domínio seljúcida", "c011cac9"], "d": ["Merâga, que estava nas mãos dos Revvâdîler, passou para o domínio seljúcida com a campanha de Tuğrul Bey no Azerbaijão.", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Tuğrul Bey entrou em Bagdade", "38af55c2"], "d": ["Tuğrul Bey, que chegou a Bagdade a convite do califa Kāim-Biemrillâh, pôs fim ao domínio buída.", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Mossul passou para as mãos dos seljúcidas", "20b8da93"], "d": ["Mossul passou, juntamente com o Iraque, para os seljúcidas; apesar da breve ocupação de Besâsîrî, permaneceu quatro anos em mãos seljúcidas.", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Mossul de novo com os Ukaylîler", "8b7c0603"], "d": ["Mossul voltou em 1061 ao domínio ukaylî; depois da tomada seljúcida de 1084, Melikşah devolveu também a cidade ao emir ukaylî.", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Alparslan pôs fim ao xainato de Najicheván", "5620360e"], "d": ["Alparslan, que derrotou os Revvâdî, aboliu o xainato de Najicheván fundado pelos Dülefî.", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["O emir Saltuk conquistou Erzurum", "f52c09dd"], "d": ["Depois de Malazgirt, Alparslan concedeu em iktâ os arredores de Erzurum ao emir Saltuk; Saltuk tomou a cidade nesse mesmo ano e foi fundado o Beilhique de Saltuklu (segundo Yinanç, 1080).", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Dânişmend Gazi conquistou Sivas", "348d7ad3"], "d": ["Dânişmend Gazi, que tomou Sivas, concedida em iktâ depois de Malazgirt, fundou aí o núcleo da dinastia (a data da conquista é discutida; há também a versão de 1080).", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Philaretos apoderou-se de Malatya", "9c80e3bd"], "d": ["Philaretos, que fundou um principado arménio na Cilícia, tomou Malatya fazendo-se passar por representante bizantino e governou-a por meio de governadores (Gabriel e outros).", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["O emir Dânişmend conquistou Tokat", "c9321fb6"], "d": ["Depois da vitória de Malazgirt, o emir Dânişmend tomou Tokat a Bizâncio.", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["Os seljúcidas tomaram Hasankeyf aos Mervânîs", "4fa9d559"], "d": ["No tempo de Melikşah, os seljúcidas puseram fim ao domínio mervânî e tomaram também Hasankeyf.", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["O filho de Fahrüddevle tomou Âmid, terminou o domínio mervânî", "ecaf6b03"], "d": ["Zaîmürrüesâ, filho de Fahrüddevle İbn Cehîr, encarregado por Melikşah, tomou Âmid aos Mervânîs.", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Tutuş apoderou-se de Diyarbekir", "469b8ebc"], "d": ["Tutuş, que pretendia o sultanato depois da morte de Melikşah, tomou a região de Diyarbekir e fez prisioneiro o último emir mervânî, Mansûr.", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["O bei turcomano Sadr começou a reinar em Âmid", "3d67b786"], "d": ["Depois da morte de Tutuş, o bei turcomano Sadr dominou Âmid; o seu sucessor İnal fundou a dinastia dos İnaloğulları.", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Kürboğa apoderou-se de Mossul", "462a238f"], "d": ["O emir seljúcida Kürboğa tomou Mossul aos Ukaylîler. (Zilkade 489 / novembro de 1096; o atlas, conformando-se à ficha, escreve com precisão de ano.)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Niksar sob domínio dos Dânişmendliler — testemunho datado da fonte", "81181870"], "d": ["A fonte mostra a cidade de Niksar nesta data sob administração dos Dânişmendliler; a posse anterior não está datada na fonte (o atlas deixa vazio o que antecede esta data).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["O dânişmendlí Gümüştegin Gazi tomou Malatya", "87f1166c"], "d": ["Gümüştegin Gazi apoderou-se de Malatya no fim de um cerco.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Kılıcarslan I recebeu Malatya", "eca366d5"], "d": ["Depois da morte de Gümüştegin, Kılıcarslan I anexou Malatya às terras seljúcidas com um cerco de mais de dois meses.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["O mezyedí Sadaka morreu em Nu'maniye, Hille passou para os seljúcidas", "e5ecea7c"], "d": ["Muhammed Tapar derrotou Sadaka; o seu filho Dübeys foi feito prisioneiro e não lhe foi permitido regressar a Hille.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["İlarslan retomou Elbistan a Tancredo", "923962c2"], "d": ["İlarslan, atabeg de Tuğrul Arslan, melik de Malatya, retomou Elbistan, que fora tomada por Tancredo, príncipe de Antioquia.", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["O artuklí Belek dominou Harput", "83425a6e"], "d": ["Belek b. Behrâm, neto de Artuk Bey, dominou Harput e fundou o seu beilhique centrado em Palu.", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Niğde sob domínio do Estado Seljúcida da Anatólia (Turquia) — testemunho datado da fonte", "dfb24c4b"], "d": ["A fonte mostra a cidade de Niğde nesta data sob administração do Estado Seljúcida da Anatólia (Turquia); a posse anterior não está datada na fonte (o atlas deixa vazio o que antecede esta data).", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Dübeys regressou a Hille", "9bc0e03a"], "d": ["Depois da morte de Muhammed Tapar, Dübeys pôde ir a Hille no tempo do sultão seljúcida do Iraque, Mahmud.", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Mahmud foi proclamado em Bagdade sultão seljúcida do Iraque — fundado o Estado Seljúcida do Iraque", "18babf94"], "d": ["Depois da morte de Muhammed Tapar, o seu filho Mahmud foi proclamado sultão pelo califa; foi fundado o Estado Seljúcida do Iraque. Bagdade, juntamente com Mossul e Tikrit, permaneceu ligada ao sultanato seljúcida do Iraque, e o Azerbaijão (Merâga, Najicheván) coube também à parte dos seljúcidas do Iraque. Tikrit surge na fonte neste ano como iktâ do şahne de Bagdade.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["João II Comneno retomou Denizli", "cb523c0f"], "d": ["O imperador bizantino João II Comneno forçou a retirar-se Alp Kara, comandante seljúcida em Laodiceia; as terras de Denizli voltaram a passar para Bizâncio (o verbete de Bizâncio diz 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Aksungur el-Ahmedîlî foi enviado a Merâga", "7a3d6deb"], "d": ["O sultão Mahmud enviou Aksungur el-Ahmedîlî a Merâga; o atabegado Ahmedîlî estabeleceu-se na cidade.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-01-01:0":{"b": ["O dânişmendlí Emîr Gazi tomou Malatya; Elbistan passou também para os Dânişmendliler", "97f3f958"], "d": ["Depois da morte de Belek, Emîr Gazi tomou Malatya, com um longo cerco, a Tuğrul Arslan, melik seljúcida; com a conquista da região de Malatya, Elbistan entrou também na administração dânişmendlí.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["Emîr Gazi tomou Ankara aos seljúcidas", "25b745cd"], "d": ["O dânişmendlí Emîr Gazi tomou Ankara a Melik Arab, filho de Kılıcarslan I, derrotando-o.", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["İmâdüddin Zengî atabeg de Mossul (Zengîler)", "ba79276b"], "d": ["O sultão seljúcida do Iraque Mahmud concedeu Mossul em iktâ a İmâdüddin Zengî; foi fundado o Atabegado de Mossul.", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Kayseri sob domínio dos Dânişmendliler — testemunho datado da fonte", "3b9b8604"], "d": ["A fonte mostra a cidade de Kayseri nesta data sob administração dos Dânişmendliler; a posse anterior não está datada na fonte (o atlas deixa vazio o que antecede esta data).", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Kemah sob domínio dos Mengücüklüler (Mengücekoğulları) — testemunho datado da fonte", "d86927c6"], "d": ["A fonte mostra a cidade de Kemah nesta data sob administração dos Mengücüklüler (Mengücekoğulları); a posse anterior não está datada na fonte (o atlas deixa vazio o que antecede esta data).", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["O sultão Mesud tomou Elbistan", "825e2c56"], "d": ["Mesud I tomou Elbistan e Ceyhan, que estavam nas mãos de Aynüddevle, e nomeou melik o seu filho Kılıcarslan.", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Najicheván foi anexada pelos İldenizliler", "774400cc"], "d": ["Com a desintegração dos seljúcidas, Najicheván juntou-se ao Estado dos İldenizliler e foi o seu centro até 1174 (o ano da anexação é sem ano; início da dinastia).", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Tikrît passou para os Begteginidas (EI2)", "a2caf5af"], "d": ["Segundo o que o TDV transmite da EI2, Tikrît esteve sob o domínio dos Begteginidas entre 1149 e 1190.", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-01-01:0":{"b": ["O sultão Mesud entregou Hille a Sâlârkerd", "4bdbd034"], "d": ["Após a morte do mezyedida Ali, o sultão Mesud entregou Hille ao seu comandante Sâlârkerd.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-01-01:0":{"b": ["O sultão Mesud morreu; o califa Muktefî tornou-se o único senhor do Iraque e tomou Hille, Kûfe e Vâsıt", "21192405"], "d": ["Com a morte do sultão Mesud, o califa Muktefî-Liemrillâh estabeleceu em Bagdade e no Iraque um domínio independente da influência seljúcida; o vizir do califa apoderou-se de Hille, e Kûfe e Vâsıt também foram conquistadas.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Yağıbasan conquistou Elbistan", "824708d3"], "d": ["Após a morte de Mesud, o melique danişmendida de Sivas, Yağıbasan, tomou Elbistan; por acordo, a administração foi-lhe deixada.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Os comandantes seljúcidas tomaram Hille, os Mezyedidas ficaram sujeitos ao naíb", "43afd955"], "d": ["Hille foi tomada pelos comandantes do sultão Muhammed b. Mahmûd; os Mezyedidas continuaram a governar como súbditos do naíb do sultão.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Baku sob domínio dos Shirvanshahs — testemunho datado da fonte", "1f2863e4"], "d": ["A fonte mostra a cidade de Baku sob a administração dos Shirvanshahs nesta data; a posse anterior não está datada na fonte (o atlas deixa em branco o período anterior a esta data).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["O califa Müstencid tomou Hille, os Mezyedidas chegaram ao fim", "4348923c"], "d": ["As tropas do califa Müstencid e dos Benî Müntefik ocuparam Hille, e os Mezyedidas foram dispersados.", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Kılıcarslan II tomou Elbistan e Darende", "7c109007"], "d": ["Aproveitando as disputas entre os danişmendidas, Kılıcarslan II apoderou-se de Elbistan, Darende e da região de Gedük.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["Rupenida Mleh tomou Tarso aos Bizantinos", "2f98fd11"], "d": ["Com a ajuda de Nûreddin Zengî, o rupenida Mleh recuperou Adana, Misis e Tarso aos Bizantinos.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["O ildenizida Pehlivan tomou Tabriz", "f0831f17"], "d": ["O ildenizida Pehlivan tomou Tabriz aos Ahmedîlîs por via pacífica e entregou-a ao seu irmão Kızılarslan.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Kılıcarslan II tomou Sivas e Niksar aos Danişmendidas", "584575bb"], "d": ["Após a morte de Nûreddin Zengî, Kılıcarslan II conquistou, no verão de 1175, Sivas, Niksar, Tokat e as restantes terras danişmendidas; o ramo de Sivas chegou ao fim.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Kılıcarslan II tomou Malatya, o ramo danişmendida terminou", "3bdbb060"], "d": ["Após um cerco de quatro meses, Malatya passou para os Seljúcidas e o ramo de Malatya dos Danişmendidas chegou ao fim.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Saladino tomou Âmid e entregou-a ao artúquida Nûreddin Muhammed", "8c3cc7bb"], "d": ["Selâhaddîn-i Eyyûbî cercou e tomou Âmid e entregou Hısnıkeyfâ ao emir artúquida Nûreddin Muhammed; os Inalidas chegaram ao fim.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Rupen III recuperou Adana aos Cruzados", "e9876f85"], "d": ["O rupenida Rupen III recuperou em 1184 Misis, Adana e Tel Hamdûn, que, após Mleh, tinham passado por algum tempo para os Cruzados.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Tikrît passou para os Abássidas", "e8f5aeac"], "d": ["Após o domínio begteginida, a cidade passou para a administração do califado abássida.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Rükneddin Süleyman Şah II recuperou Samsun", "0971ebcd"], "d": ["Samsun e as terras do Mar Negro oriental, que tinham passado para os Comnenos durante as disputas entre irmãos, foram recuperadas por Süleyman Şah.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Adana e Tarso: o principado rupenida transformou-se no Reino Arménio da Cilícia", "de3c4beb"], "d": ["A dinastia rupenida, que detinha Adana e Tarso, assumiu o título de rei; trata-se de uma mudança de título da mesma dinastia, o território não mudou de mãos. O dia da coroação NÃO FOI ENCONTRADO no TDV — a data foi herdada do início da ficha do Reino Arménio da Cilícia (o dia da ficha não é fonte).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["Fundado o Império de Trebizonda — Giresun e Sinope também dentro das suas fronteiras", "a99b6ba0"], "d": ["Com a tomada de Constantinopla pelos Latinos, Aleksios Komnenos, que fugira para Trebizonda, proclamou-se imperador; a cidade tornou-se o centro do novo Estado. O Estado fundado pelos netos dos Comnenos, Aleksios e David, estendeu-se até Sinope; Giresun também ficou dentro das fronteiras do Império de Trebizonda.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Kütahya sob domínio do Império de Niceia (Láscaris) — testemunho datado da fonte", "d91fa405"], "d": ["A fonte mostra a cidade de Kütahya sob a administração do Império de Niceia (Láscaris) nesta data; a posse anterior não está datada na fonte (o atlas deixa em branco o período anterior a esta data).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["O ildenizida Ebû Bekir tomou Merâga", "03faed10"], "d": ["O ahmedîlî Alâeddin Körpearslan foi obrigado a deixar a fortaleza de Merâga ao atabegue ildenizida Ebû Bekir.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["Os Seljúcidas conquistaram Denizli e Honaz", "1053ccc8"], "d": ["No segundo reinado de Gıyâseddin Keyhusrev I, Denizli e Honaz passaram para os Seljúcidas (as fontes bizantinas dizem 1196, o artigo selcuklular diz 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-01-01:0":{"b": ["Gıyâseddin Keyhusrev I anexou de novo Maraş aos Seljúcidas", "91b1544e"], "d": ["Keyhusrev organizou uma campanha contra os Arménios e anexou Maraş às terras seljúcidas.", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Kastamonu sob domínio dos Çobanidas — testemunho datado da fonte", "10b682ba"], "d": ["A fonte mostra a cidade de Kastamonu sob a administração dos Çobanidas nesta data; a posse anterior não está datada na fonte (o atlas deixa em branco o período anterior a esta data).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["İzzeddin Keykâvus I conquistou Sinope", "463ea2b9"], "d": ["O sultão seljúcida İzzeddin Keykâvus I tomou Sinope aos Comnenos de Trebizonda.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Alâeddin Keykubad I tomou Kalonoros (Alâiye)", "5a4d6ac2"], "d": ["A fortaleza de Kalonoros, a leste de Antália, foi tomada pelos Seljúcidas, reconstruída e recebeu o nome de Alâiye (o artigo alanya diz 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Celâleddin Hârizmşah anexou o Azerbaijão", "5b812b99"], "d": ["Celâleddin Hârizmşah anexou aos seus territórios o Azerbaijão e Arrân (frase sobre a região).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Celâleddin Hârizmşah tomou Merâga", "a55ec004"], "d": ["Celâleddin Hârizmşah conquistou Merâga e fez dela o centro militar e administrativo no Azerbaijão.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Celâleddin Hârizmşah entrou em Tabriz", "72904097"], "d": ["Quando o atabegue Özbek se retirou para Gence, Celâleddin Hârizmşah entrou em Tabriz, assenhoreou-se da cidade e fez dela o seu centro.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Alâeddin Keykubad tomou Kemah", "8c5aa655"], "d": ["O ramo Kemah-Erzincan dos Mengücekidas foi anexado às terras seljúcidas por Alâeddin Keykubad I, que cercou e tomou Kemah.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Merâga foi tomada pelos Mongóis pela segunda vez", "f1320e5d"], "d": ["No fim do domínio dos Hârizmşahs, Merâga passou para as mãos dos Mongóis.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["O Azerbaijão entrou sob domínio mongol — Tabriz sofreu a ocupação mongol", "3f38ef66"], "d": ["Com o colapso de Celâleddin Hârizmşah, Tabriz sofreu a ocupação mongol em 1231; o domínio mongol abrangeu nesse mesmo ano o Azerbaijão do Norte e do Sul (frase sobre a região, não específica da cidade). Em Shirvan (Baku, Shamakhi), os Shirvanshahs continuaram a existir como dinastia local sob a soberania mongol; o atlas mantém estes dois pontos na cor dos Shirvanshahs por decisão de Emre (a sujeição mongol/ilcânida consta da nota).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["O aiúbida al-Melikü'l-Kâmil tomou Âmid", "9cebe681"], "d": ["Al-Melikü'l-Kâmil cercou Âmid e tomou-a aos Artúquidas.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Alâeddin Keykubad I tomou Kütahya ao Império de Niceia", "e0b9a7f7"], "d": ["Kütahya, que passara de novo para Bizâncio nas convulsões posteriores a 1182, foi recuperada ao Império de Niceia no tempo de Alâeddin Keykubad I.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Bedreddin Lü'lü' sultão de Mossul", "73268628"], "d": ["Com a morte do último atabegue zengida, Bedreddin Lü'lü' foi proclamado sultão pelo califa. (Rebîülevvel 631 / dezembro de 1233; o atlas, seguindo a ficha, escreve com precisão de ano.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["Os Seljúcidas tomaram Harput", "3b9391eb"], "d": ["O exército de Alâeddin Keykubad recebeu a rendição da fortaleza de Harput após um cerco de vinte e quatro dias; os Artúquidas de Harput chegaram ao fim.", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-01-01:0":{"b": ["Gıyâseddin Keyhusrev II conquistou Âmid", "c37c3b04"], "d": ["O sultão seljúcida da Anatólia Gıyâseddin Keyhusrev II tomou Âmid aos Aiúbidas.", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Möngke Khan nomeou İftihârüddin governador de Qazvin", "fc650d13"], "d": ["O Grande Khan mongol Möngke nomeou um governador para Qazvin; começou o período dos İftihârîs.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Chegada de Hülâgû: Qazvin e Najicheván passaram para a administração ilcânida", "24673608"], "d": ["Com a chegada de Hülâgû ao Irão, a administração mongol passou para o Estado Ilcânida; Qazvin e Najicheván passaram para a administração ilcânida (limite da regra 5, não o dia da fonte). Em Shirvan (Baku, Shamakhi), a ocupação mongol trouxe grande destruição, mas os Shirvanshahs continuaram como dinastia local; o atlas mantém estes dois pontos na cor dos Shirvanshahs (decisão de Emre).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["Os Mongóis ocuparam Tikrit", "60af2df0"], "d": ["Durante a invasão mongol, Tikrit foi ocupada e saqueada; a cidade saiu da administração abássida.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Hülâgû marchou de Hamadã para Bagdade", "5f0c77b5"], "d": ["Hülâgû partiu para a campanha de Bagdade a partir de Hamadã, onde se encontrava a sua bagagem (testemunho do domínio ilcânida).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Boğatimur tomou Kûfe e Baçorá", "dec82b4e"], "d": ["As forças mongóis sob o comando de Boğatimur apoderaram-se de Kûfe, Vâsıt e Baçorá.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["O Iraque passou para as mãos dos Mongóis (regional)", "7b990281"], "d": ["Com a ocupação de Bagdade por Hülâgû em 1258, o Estado Abássida foi destruído e o Iraque passou para as mãos dos Mongóis.", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Maraş foi deixada aos Arménios", "6161f1a5"], "d": ["İmâdüddin, da família de Hüsâmeddin, não encontrando apoio, abandonou Maraş aos Arménios da Cilícia.", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Vâsıt passou para o domínio ilcânida", "fbdf83fc"], "d": ["Com a conquista do Iraque pelos Ilcânidas, Vâsıt entrou sob a sua administração.", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["Os Mongóis tomaram Bagdade; fim do califado abássida", "41c34bd4"], "d": ["Os Mongóis sob o comando de Hülâgû atacaram Bagdade, o califa Müsta‘sım rendeu-se; a cidade passou para o domínio ilcânida.", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["Os Mongóis tomaram Mossul, a dinastia Lü'lü' chegou ao fim", "035d0121"], "d": ["Mossul, de al-Melikü's-Sâlih İsmâil, que estava ao lado de Baybars, sofreu a devastação mongol, e ele próprio foi morto na presença de Hülâgû.", "69cc41a9"]},
"OLAYLAR_T5_1000B:1070-01-01:0":{"b": ["O sermão de Meca foi mudado dos Fatímidas para o califa abássida e o sultão Alparslan", "df951887"], "d": ["Como, devido à fome no Egito, os mantimentos deixaram de chegar, o emir de Meca, Ebû Hâşim Muhammed b. Ca‘fer, fez recitar o sermão em nome do califa abássida Kāim-Biemrillâh e do sultão seljúcida Alparslan; Meca passou para a suserania dos Grandes Seljúcidas.", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Atsız b. Uvak tomou Damasco", "8eea047f"], "d": ["Atsız apoderou-se da Síria e fez recitar o sermão em nome do califa abássida e de Melikşah.", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["O emir de Meca, Ebû Hâşim, fez recitar de novo o sermão em nome do califa fatímida", "85b6c0c0"], "d": ["Apesar dos esforços de Melikşah para consolidar a influência sunita, o emir de Meca voltou a fazer recitar o sermão em nome dos Fatímidas; Meca regressou à suserania fatímida.", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Tutuş entrou em Damasco, fundados os Seljúcidas da Síria", "b48b38be"], "d": ["Tutuş entrou na cidade e fundou o Estado Seljúcida da Síria.", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["O emir de Meca declarou lealdade ao califa abássida Muktedî e ao sultão Melikşah", "38a430a5"], "d": ["O emir de Meca submeteu-se de novo ao califa abássida e ao sultão seljúcida; esta lealdade durou até à morte de Melikşah (1092).", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["Com a morte do sultão Melikşah, o sermão em Meca voltou aos Fatímidas", "195a27cd"], "d": ["Quando o sultão seljúcida Melikşah morreu, o emir de Meca voltou a fazer recitar os sermões em nome do califa fatímida; Meca passou para a suserania fatímida.", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["Após a derrota de Dorileu, Eskişehir regressou a Bizâncio", "3f381ee4"], "d": ["Após a retirada de Kılıcarslan I diante dos Cruzados, a cidade voltou a entrar sob a administração bizantina.", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Tuğtegin fundou o Atabegado de Damasco", "f26729c0"], "d": ["Após a morte de Dukak, o atabegue Tuğtegin fundou a dinastia dos Búridas.", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["Os Almóadas tomaram Meknès", "ee976b41"], "d": ["Após longa resistência, a cidade entrou sob o domínio almóada e foi saqueada.", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nûreddin Zengî tomou Damasco", "a4fd8b58"], "d": ["Nûreddin Mahmud colocou Damasco sob o seu domínio.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Terminou a administração fatímida no Egito, os Aiúbidas assumiram o poder — Alexandria, Faium e Meca (Hejaz)", "1c565534"], "d": ["Com o vizirato de Saladino e a morte do califa fatímida Âdıd (567/1171), o Egito passou para os Aiúbidas; Alexandria e Faium entraram sob a administração aiúbida. Não há dia na fonte — foi herdado do fim da ficha fatímida (o dia da ficha não é fonte). O Hejaz também entrou sob a administração aiúbida; a suserania de Meca passou dos Fatímidas para os Aiúbidas (modelo de suserano, Emre #23).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Saladino tomou Damasco", "dfdb11ce"], "d": ["Após a morte de Nûreddin, a cidade passou para Selâhaddîn-i Eyyûbî.", "a20855b8"]},
"OLAYLAR_T5_1000B:1175-07-22:0":{"b": ["Os Aiúbidas tomaram Adén, os Zuray‘idas chegaram ao fim", "d253acf0"], "d": ["Os Aiúbidas avançaram sobre Adén e executaram o vizir Yâsir b. Bilâl.", "06e4a877"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Após Miriocéfalo, Bizâncio evacuou Dorileu", "24aef255"], "d": ["Após a derrota de Miriocéfalo, Manuel, em cumprimento do tratado, demoliu as fortificações de Dorileu e esvaziou a cidade; os Turcos começaram a chamar-lhe Eskişehir.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasya foi anexada às terras seljúcidas", "cf56b964"], "d": ["Kılıcarslan II anexou ao país seljúcida as terras danişmendidas (incluindo Amasya).", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Os irmãos Asen tomaram a Bulgária do Norte; Bizâncio reconheceu o Segundo Estado Búlgaro", "ff0554e9"], "d": ["Os irmãos Petar e Asen retomaram a Bulgária do Norte com o apoio dos Cumanos; com a paz de 1187, Bizâncio reconheceu o Segundo Estado Búlgaro.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["A Sérvia consolidou o seu domínio em Zeta", "794c821d"], "d": ["Em 1189, a Sérvia consolidou o seu domínio sobre Zeta (incluindo a costa de Kotor); foi reconhecido a Zeta um estatuto especial.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Guy de Lusignan comprou Chipre, Nicósia tornou-se capital", "11017aea"], "d": ["Guy de Lusignan comprou a ilha aos Templários e fez de Nicósia a capital.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Kaloyan apoderou-se de Varna", "1237fe7f"], "d": ["Os Búlgaros sob o comando do czar Kaloyan tomaram Varna a Bizâncio em março de 1201; a cidade permaneceu dentro das fronteiras do Estado Búlgaro nos séculos XIII-XIV.", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Nîşâbur foi definitivamente anexada aos Hârizmşahs", "fa4a6cd2"], "d": ["Alâeddin Muhammed b. Tekiş anexou definitivamente a cidade às terras dos Hârizmşahs.", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["A península de Galípoli entrou sob administração latina", "27308f59"], "d": ["Após a Quarta Cruzada, Galípoli e a sua região passaram em 1204 para a administração dos Latinos.", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["Fundado o Despotado do Epiro — Jânina tornou-se o centro, Naupacto passou para o despotado", "d7966877"], "d": ["Após a Quarta Cruzada, Miguel Ângelo fundou o Despotado do Epiro; Jânina foi feita centro do despotado e Naupacto também ficou dentro das terras do despotado.", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["Creta foi vendida a Veneza", "f1760e84"], "d": ["Por acordo de 12 de agosto de 1204, o marquês Bonifácio de Monferrato cedeu Creta a Veneza por 100.000 de prata.", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["Fundada Mansûra", "342a6f47"], "d": ["Al-Melikü'l-Kâmil fundou Mansûra como acampamento contra os Cruzados que ocupavam Damieta.", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["Os Mongóis tomaram Nîşâbur", "0e73f075"], "d": ["Com a invasão mongol, a cidade foi destruída.", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["O rasúlida Nûreddin Ömer colocou o Iémen sob o seu domínio", "ee1ec7ab"], "d": ["Após a morte de al-Mes‘ûd, o último aiúbida do Iémen, Nûreddin Ömer assenhoreou-se do Iémen.", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["O imperador de Niceia Vatatzes recuperou Galípoli", "a6936e33"], "d": ["O imperador de Niceia João III Vatatzes recuperou Galípoli aos Latinos (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["Os Mongóis conquistaram Amasya", "783bcd0c"], "d": ["Depois de Kösedağ, os Mongóis tomaram a cidade e governadores mongóis administraram-na.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vatatzes passou à Trácia: Adrianópolis e Salonica foram anexadas ao Império de Niceia", "0bf61ca5"], "d": ["O soberano de Niceia João III Vatatzes passou em 1246 à Trácia e apoderou-se das terras ocupadas pelos Búlgaros e de Salonica.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["A soberania rasúlida era reconhecida em Meca — Nûreddin Ömer foi vítima de assassinato", "d7e03c21"], "d": ["Quando o sultão rasúlida do Iémen Nûreddin Ömer foi morto em Cened (fevereiro de 1250), a soberania do seu Estado era reconhecida entre Meca e Hadramaut; no ano em que terminou o sultanato aiúbida, Meca aparece sob a suserania rasúlida.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["Fundado o Estado Mameluco no Egito — Alexandria, Mansûra e Faium passaram para os Mamelucos", "230c1a11"], "d": ["Após Turan Şah, com Şecerüddür e İzzeddin Aybek foi estabelecido o poder mameluco; as cidades do Egito (Alexandria, Mansûra, Faium) passaram para a administração mameluca. A fonte dá a ascensão de Aybek ao trono em 3 de julho de 1250; o atlas herdou o dia do fim da ficha aiúbida (30 de abril de 1250) — o dia da ficha não é fonte, a diferença foi comunicada.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["O aiúbida de Alepo, en-Nâsır Yûsuf, assenhoreou-se de Damasco", "d585985d"], "d": ["Enquanto o poder mameluco se estabelecia no Egito, o senhor de Alepo, en-Nâsır Yûsuf, tomou Damasco (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Jerusalém foi deixada aos Mamelucos por paz", "50d53fac"], "d": ["Com a paz feita por mediação do califa, Jerusalém foi deixada aos Mamelucos.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Jerusalém passou de novo para os Aiúbidas", "fdeedd4a"], "d": ["A Palestina e Jerusalém passaram de novo para as mãos dos Aiúbidas da Síria.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Os Mongóis tomaram Damasco", "430bdfea"], "d": ["Na campanha de Hülâgû na Síria, Damasco passou para os Mongóis.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Batalha de Ain Jalut: Damasco e Jerusalém passaram para os Mamelucos", "40ebd7b7"], "d": ["Kutuz derrotou os Mongóis em Aynicâlût (25 Ramazan 658 / 3 de setembro de 1260); a maior parte da Síria, Damasco e Jerusalém passaram para as mãos dos Mamelucos, e a dinastia aiúbida chegou ao fim.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Baybars restaurou o califado abássida no Cairo — Meca e Medina foram ligadas aos Mamelucos", "a5128a1e"], "d": ["Baybars proclamou califa no Cairo o abássida Ahmed, sobrevivente da destruição de Bagdade, e prestou-lhe juramento de fidelidade; na qualidade de protetor do califado, ligou também os Haremeyn à suserania mameluca. O dia é o da restauração do califado; o dia da ligação de Meca e Medina não consta da fonte (limite inferior).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["As tropas de Niceia entraram em Constantinopla — o Império Bizantino foi restabelecido", "81741490"], "d": ["As tropas de Niceia entraram em Constantinopla em 25 de julho de 1261 e puseram fim ao domínio latino; as terras do Estado láscarida (de Niceia) — Bursa, Esmirna, Çimpe, Adrianópolis, Salonica — tornaram-se de novo Império Bizantino. O atlas mostra o período do Império de Niceia anterior a 1261 nestes pontos apenas quando são mencionados pelo nome na fonte.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Carlos de Anjou tomou Durrës e Krujë", "082a86b8"], "d": ["Carlos, da dinastia de Anjou, tomou Durrës e Krujë em 1271-1272 e mandou reconstruir a antiga fortaleza.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Os Sicilianos ocuparam a ilha de Djerba", "daab5ad2"], "d": ["A ilha de Djerba foi ocupada pelos Sicilianos no ano 683 (1284-85); foi primeiro domínio do papado e depois ficou ligada ao Reino da Sicília.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Jânina foi anexada de novo ao Império Bizantino", "60016303"], "d": ["Jânina, que mudou de mãos muitas vezes na segunda metade do século XIII, foi anexada de novo a Bizâncio em 1318, mas conservou até certo ponto a sua autonomia; o centro do Despotado do Epiro passou para Arta.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["O povo de Djerba expulsou os Sicilianos da ilha", "ff71985e"], "d": ["O povo da ilha, que se revoltou contra a má administração dos governadores sicilianos, expulsou os Sicilianos em 1334; Djerba voltou a entrar sob administração hafsida.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Carlos Thopia assenhoreou-se de Krujë", "4e40583d"], "d": ["Após a morte do czar Dušan (1355), o albanês Carlos Thopia assenhoreou-se de Krujë.", "7af64cd2"]}
});
